	//         const menuInfo = dlt_menu.getMatchedJSON("MENU_CD", menuCd);

	//         if ((menuInfo.length > 0) && (!$c.util.isEmpty(menuInfo[0].SRC_PATH))) {
	//             const option = {
	//                 isHistory: true
