};

/* ==========================================================================
 * 2. 탭 전환 (전체메뉴 / 즐겨찾기 / 시작메뉴)
 * ========================================================================== */

/**
 * @event
 * @name anc_menu_onclick
 * @description 전체메뉴 탭 클릭 시 발생하는 이벤트 정의
 */
scwin.anc_menu_onclick = function () {
	// 탭 CSS 적용
	grp_allMenu.addClass('on');
	grp_favMenu.removeClass('on');
	grp_startMenu.removeClass('on');

	// 탭 내용 표시
	gr_tab_menu.setStyle("display", "block");
	gr_tab_menu02.setStyle("display", "none");
	gr_tab_menu03.setStyle("display", "none");
};

/**
 * @event
 * @name anc_menu02_onclick
 * @description 즐겨찾기 버튼 클릭 시 발생하는 이벤트 정의
 */
scwin.anc_menu02_onclick = function () {
	// 탭 CSS 적용
	grp_favMenu.addClass('on');
	grp_allMenu.removeClass('on');
	grp_startMenu.removeClass('on');

	// 탭 내용 표시
	gr_tab_menu.setStyle("display", "none");
	gr_tab_menu02.setStyle("display", "block");
	gr_tab_menu03.setStyle("display", "none");
	gr_search_field.removeClass("active");

	// 즐겨찾기 메뉴 구성 - 이미 생성된 자식 노드는 다시 만들지 않고 재사용한다.
	// (즐겨찾기 추가/삭제에 따른 노드 갱신은 updateFav 가 담당한다)
	if (gen_fav.getChildrenCount() <= 0) {
		const fav = dlt_fav.getAllJSON();

		for (let i = 0; i < fav.length; i++) {
			gen_fav.insertChild(i);
			const child = gen_fav.getChild(i, 'btn_fav');
			child.setValue(fav[i].MENU_NM);
			child.setUserData('menuCode', fav[i].MENU_CD);
		}
	}
};

/**
 * @event
 * @name anc_menu03_onclick
 * @description 시작메뉴 탭 클릭 시 발생하는 이벤트 정의
 */
scwin.anc_menu03_onclick = function () {
	// 탭 CSS 적용
	grp_startMenu.addClass('on');
	grp_allMenu.removeClass('on');
	grp_favMenu.removeClass('on');

	// 탭 내용 표시
	gr_tab_menu.setStyle("display", "none");
	gr_tab_menu02.setStyle("display", "none");
	gr_tab_menu03.setStyle("display", "block");
	gr_search_field.removeClass("active");
};

/* ==========================================================================
 * 3. 메뉴 트리 생성·펼침·접힘
 * ========================================================================== */

/**
 * @method
 * @name initGen
 * @description 최초화면 로딩 시 셋팅될 1depth Menu를 만든다.
 * @hidden N
 * @example
 * scwin.initGen();
 */
scwin.initGen = function () {
	const first = dlt_menu.getMatchedJSON("MENU_LEVEL", 1);

	for (let i = 0; i < first.length; i++) {
		gen_depth1.insertChild(i);

		const child = gen_depth1.getChild(i, "btn_depth1");
		child.setValue(first[i].MENU_NM);
		child.setUserData('menuCode', first[i].MENU_CD);

		// no_depth Class
		const length = dlt_menu.getMatchedJSON("PARENT_MENU_CD", first[i].MENU_CD).length;
		if (length <= 0) gen_depth1.getChild(i, 'grp_1depth').addClass('no_depth');
	}
};

/**
 * @method
 * @name secondGen
 * @description 1depth 메뉴 버튼을 눌렀을 때 2depth 메뉴를 표시한다.
 * 1Depth의 메뉴가 화면이 있는 경우 해당 화면을 호출한다.
 * 이미 생성된 2depth 자식 노드는 다시 만들지 않고 재사용하며, 접힘/펼침 상태만 토글한다.
 * @hidden N
 * @example
 * // gen_depth1 내부 btn_depth1 의 onclick 으로 호출된다. (this = 클릭된 btn_depth1)
 * btn_depth1.click();
 */
scwin.secondGen = function () {
	const pMenuCd = this.getUserData('menuCode');
	const first = dlt_menu.getMatchedJSON("MENU_CD", pMenuCd);

	// idx search
	const idx = this.getGeneratedIndex();
	const grp = this.getGenerator().getChildren()[idx];

	// 2depth Generator
	const gen = grp.getChildren()[1];

	// 1Depth의 화면이 있는 경우 실행
	if (first[0].SRC_PATH != '' && first[0].SRC_PATH != undefined) {
		scwin.menubtn_onclick(first);
		grp.addClass('on');
	}

	if (gen.getChildrenCount() > 0) {
		// 이미 생성된 자식 노드는 재사용: 접힘/펼침 상태만 토글한다.
		grp.toggleClass('on');
	} else {
		const second = dlt_menu.getMatchedJSON('PARENT_MENU_CD', pMenuCd);

		for (let i = 0; i < second.length; i++) {
			gen.insertChild(i);
			const child = gen.getChild(i, 'btn_depth2');
			child.setValue(second[i].MENU_NM);
			child.setUserData('menuCode', second[i].MENU_CD);

			// no_depth Class
			const length = dlt_menu.getMatchedJSON("PARENT_MENU_CD", second[i].MENU_CD).length;
			if (length <= 0) gen.getChild(i, 'grp_2depth').addClass('no_depth');
		}

		grp.addClass('on');
	}

	const deviceWidth = $c.num.parseFloat($("body").css("width"));

	// 모바일일 경우 후처리로 접히지
	if (deviceWidth > 1280) {
		// menu가 접힌 경우 펼친다.
		scwin.collapseMenu();
	}
};

/**
 * @method
 * @name thirdGen
 * @description 2Depth 메뉴 버튼을 클릭했을 때 3Depth 메뉴를 표시한다.
 * 2Depth 화면이 있을 경우 호출한다.
 * 이미 생성된 3depth 자식 노드는 다시 만들지 않고 재사용하며, 접힘/펼침 상태만 토글한다.
 * @hidden N
 * @example
 * // gen_depth2 내부 btn_depth2 의 onclick 으로 호출된다. (this = 클릭된 btn_depth2)
 * btn_depth2.click();
 */
scwin.thirdGen = function () {
	const pMenuCd = this.getUserData('menuCode');
	const second = dlt_menu.getMatchedJSON("MENU_CD", pMenuCd);

	// 2Depth의 화면이 있는 경우 실행
	if (second[0].SRC_PATH != '' && second[0].SRC_PATH != undefined) {
		scwin.menubtn_onclick(second);
	}

	// idx search
	const idx = this.getGeneratedIndex();
	const grp = this.getGenerator().getChildren()[idx];

	// 3depth Generator
	const gen = grp.getChildren()[1];

	if (gen.getChildrenCount() > 0) {
		// 이미 생성된 자식 노드는 재사용: 접힘/펼침 상태만 토글한다.
		grp.toggleClass('on');
	} else {
		const third = dlt_menu.getMatchedJSON('PARENT_MENU_CD', pMenuCd);

		for (let i = 0; i < third.length; i++) {
			gen.insertChild(i);

			const child = gen.getChild(i, 'btn_depth3');
			child.setValue(third[i].MENU_NM);
			child.setUserData('menuCode', third[i].MENU_CD);

			// no_depth class
			gen.getChild(i, 'grp_3depth').addClass('no_depth');
		}

		grp.addClass('on');
	}
};

/**
 * @method
 * @name secondGenAll
 * @description 2depth 메뉴를 모두 펼친다.
 * 이미 생성된 2depth 자식 노드는 다시 만들지 않고 재사용하며, 펼침 상태(on)만 적용한다.
 * @hidden N
 * @example
 * scwin.secondGenAll();
 */
scwin.secondGenAll = function () {
	// 각 1depth 메뉴 아래에 2depth 메뉴를 그린다
	for (let i = 0; i < gen_depth1.getLength(); i++) {
		const grp = gen_depth1.getChild(i, 'grp_1depth');
		const gen = gen_depth1.getChild(i, 'gen_depth2');
		const pMenuCd = gen_depth1.getChild(i, 'btn_depth1').getUserData('menuCode');

		const second = dlt_menu.getMatchedJSON('PARENT_MENU_CD', pMenuCd);
		if (second.length <= 0) continue;

		// 이미 생성된 자식 노드는 다시 만들지 않고 재사용한다.
		if (gen.getChildrenCount() <= 0) {
			for (let j = 0; j < second.length; j++) {
				gen.insertChild(j);
				const child = gen.getChild(j, "btn_depth2");
				child.setValue(second[j].MENU_NM);
				child.setUserData('menuCode', second[j].MENU_CD);

				// no_depth Class
				const length = dlt_menu.getMatchedJSON('PARENT_MENU_CD', second[j].MENU_CD).length;
				if (length <= 0) gen.getChild(j, 'grp_2depth').addClass('no_depth');
			}
		}

		grp.addClass('on');
	}
};

/**
 * @method
 * @name thirdGenAll
 * @description 3depth 메뉴를 모두 펼친다.
 * 이미 생성된 3depth 자식 노드는 다시 만들지 않고 재사용하며, 펼침 상태(on)만 적용한다.
 * @hidden N
 * @example
 * scwin.thirdGenAll();
 */
scwin.thirdGenAll = function () {
	// 각 2depth 메뉴 아래에 3depth 메뉴를 그린다
	for (let i = 0; i < gen_depth1.getLength(); i++) {
		const gen2 = gen_depth1.getChild(i, 'gen_depth2');

		for (let j = 0; j < gen2.getLength(); j++) {
			const grp2 = gen2.getChild(j, 'grp_2depth');
			const gen3 = gen2.getChild(j, 'gen_depth3');
			const pMenuCd = gen2.getChild(j, 'btn_depth2').getUserData('menuCode');

			const third = dlt_menu.getMatchedJSON('PARENT_MENU_CD', pMenuCd);
			if (third.length <= 0) continue;

			// 이미 생성된 자식 노드는 다시 만들지 않고 재사용한다.
			if (gen3.getChildrenCount() <= 0) {
				for (let k = 0; k < third.length; k++) {
					gen3.insertChild(k);
					const child = gen3.getChild(k, 'btn_depth3');
					child.setValue(third[k].MENU_NM);
					child.setUserData('menuCode', third[k].MENU_CD);

					// no_depth class
					gen3.getChild(k, 'grp_3depth').addClass('no_depth');
				}
			}

			grp2.addClass('on');
		}
	}
};

/**
 * @method
 * @name collapseAll
 * @description 펼쳐진 모든 메뉴를 접는다.
 * @hidden N
 * @example
 * scwin.collapseAll();
 */
scwin.collapseAll = function () {
	const depth1 = dlt_menu.getMatchedJSON('MENU_LEVEL', 1);

	// 각각의 1depth 메뉴를 모두 접는다. 자식 노드는 제거하지 않고 유지하여 재사용한다.
	for (let i = 0; i < depth1.length; i++) {
		gen_depth1.getChildren()[i].removeClass('on');
	}
};

/**
 * @method
 * @name menuHandleControl
 * @description 메뉴를 모두 펼치거나, 닫히게 한다.
 * @param {boolean} chk true 면 모두 펼치고, false 면 모두 접는다
 * @hidden N
 * @example
 * scwin.menuHandleControl(true);
 */
scwin.menuHandleControl = function (chk) {
	if (chk) {
		// 초기화
		scwin.collapseAll();

		// 2depth 메뉴 모두 펼치기
		scwin.secondGenAll();

		// 3depth 메뉴 모두 펼치기
		scwin.thirdGenAll();
	} else {
		scwin.collapseAll();
	}
};

/**
 * @method
 * @name toggleMenu
 * @description 메뉴 전체 펼치기 버튼의 이미지 클래스를 전환한다.
 * @returns {boolean} 전환 전 접힘 상태 여부 (true: 접힘 상태였음)
 * @hidden N
 * @example
 * const chk = scwin.toggleMenu();
 */
scwin.toggleMenu = function () {
	const chk = btn_menuExpandAll.hasClass("btn_side_menufold");
	const oldClass = chk ? "btn_side_menufold" : "btn_side_menulist";
	const newClass = chk ? "btn_side_menulist" : "btn_side_menufold";

	btn_menuExpandAll.changeClass(oldClass, newClass);

	return chk;
};

/**
 * @event
 * @name btn_menuExpandAll_onclick
 * @description 메뉴 전체 확장 버튼 클릭 이벤트
 */
scwin.btn_menuExpandAll_onclick = function (e) {
	const chk = scwin.toggleMenu();
	scwin.menuHandleControl(chk);
};

/**
 * @method
 * @name toggle3DepthMenu
 * @description 클릭된 메뉴에만 선택 CSS(on)를 적용하고 해당 위치로 스크롤한다.
 * @param {Array} menuObj 대상 메뉴의 getMatchedJSON 결과
 * @hidden N
 * @example
 * scwin.toggle3DepthMenu(dlt_menu.getMatchedJSON("MENU_CD", "100111"));
 */
scwin.toggle3DepthMenu = function (menuObj) {
	// 1depth 메뉴의 수
	const d1cnt = gen_depth1.getLength();

	// scroll 계산을 위한 변수
	const id = gr_tab_menu.getID();
	const wrap = document.getElementById(id);

	// 선택된 메뉴 위치로 스크롤한다.
	// 행 인덱스 x 행 높이 방식은 MENU_LEVEL 빈 값 데이터에서 어긋나므로 실제 DOM 위치를 쓴다.
	const scrollToElement = function (element) {
		wrap.scrollTop = element.getBoundingClientRect().top - wrap.getBoundingClientRect().top + wrap.scrollTop;
	};

	for (let i = 0; i < d1cnt; i++) {
		const grp1 = gen_depth1.getChild(i, 'grp_1depth');

		// 1depth 메뉴가 화면을 가진 경우
		let children = grp1.getChildren();
		if (children[0].getValue() == menuObj[0].MENU_NM && menuObj[0].SRC_PATH != '') {
			grp1.toggleClass('on');
			scrollToElement(document.getElementById(children[0].getID()));
		}

		// 2depth Generator
		const gen2 = grp1.getChildren()[1];
		const d2cnt = gen2.getLength();

		for (let j = 0; j < d2cnt; j++) {
			const dep2Grp = gen2.getChild(j, 'grp_2depth');
			const isNodepth = dep2Grp.hasClass('no_depth');

			children = dep2Grp.getChildren();
			if (isNodepth) dep2Grp.removeClass('on');

			// 2depth 메뉴가 화면을 가진 경우
			if (children[0].getValue() == menuObj[0].MENU_NM && menuObj[0].SRC_PATH != '') {
				dep2Grp.toggleClass('on');
				scrollToElement(document.getElementById(children[0].getID()));
			}

			// 3depth Generator
			const gen3 = dep2Grp.getChildren()[1];
			const d3cnt = gen3.getLength();

			for (let k = 0; k < d3cnt; k++) {
				const child = gen3.getChild(k, 'grp_3depth');
				child.removeClass('on');

				const menu = child.getChildren()[0];
				if (menu.getValue() == menuObj[0].MENU_NM) {

					// 선택된 메뉴 CSS 적용
					child.addClass('on');
					scrollToElement(document.getElementById(menu.getID()));
				}
			}
		}
	}
};

/**
 * @method
 * @name collapseMenu
 * @description side 메뉴 바의 접힘, 펼침 상태에 따라 동작을 결정한다. 접혀 있으면 다시 펼쳐 사용자에게 보여준다.
 * @hidden N
 * @example
 * scwin.collapseMenu();
 */
scwin.collapseMenu = function () {
	const isCollapse = $p.main().pfm_main.scope.grp_wrap.hasClass("show_menu");
	// 메뉴가 접혀있는 경우 다시 펼쳐 사용자에게 보여준다.
	if (!isCollapse) {
		$p.main().pfm_main.scope.grp_wrap.addClass("show_menu");
	}
};

/* ==========================================================================
 * 4. 메뉴 열기
 * ========================================================================== */

/**
 * @event
 * @name menubtn_onclick
 * @description 메뉴 버튼 클릭 시 발생하는 이벤트 정의
 */
scwin.menubtn_onclick = function (menuObj) {
	// menuObj에 정보가 없는 경우 직접 찾는다
	if (menuObj === undefined || menuObj === '') {
		const idx = this.getGeneratedIndex();
		const menu = this.getGenerator().getChildren()[idx];
		const menuNm = menu.getChildren()[0].getValue();
		menuObj = dlt_menu.getMatchedJSON("MENU_NM", menuNm);
	}

	// 바인딩
	scwin.setMenuRelation(menuObj[0].MENU_NM, menuObj[0].SRC_PATH, menuObj[0].MENU_CD);

	// 1depth 메뉴가 화면이 있고 하위 메뉴가 없으면 toggle3DepthMenu를 실행하지 않는다
	// (최상위 메뉴의 부모 코드는 빈 값 또는 "000000000" 두 형태가 있다)
	const parentCd = menuObj[0].PARENT_MENU_CD;
	if (($c.util.isEmpty(parentCd) || parentCd == '000000000') && menuObj[0].SRC_PATH != '') {
		return;
	}

	// CSS 적용
	scwin.toggle3DepthMenu(menuObj);
};

/**
 * @method
 * @name setMenuRelation
 * @description 메뉴를 open할 때 관련된 기능들을 경우에 따라 처리해준다.
 * @param {string} menuNm 메뉴 명
 * @param {string} menuUrl 메뉴 URL
 * @param {string} menuCode 메뉴 코드
 * @param {string} skipType Tree Node 선택 여부 ("Tree" || null)
 * @hidden N
 * @example
 * scwin.setMenuRelation("인사조회", "/tmp/tmp01.xml", "010001");
 * scwin.setMenuRelation("인사조회", "/tmp/tmp01.xml", "010001", "Tree");
 */
scwin.setMenuRelation = function (menuNm, menuUrl, menuCode, skipType) {
	const menuList = dlt_menu.getMatchedJSON("MENU_CD", menuCode, true);

	if (menuList && menuList.length > 0) {
		const option = {
			isHistory: true,
			closable: true
		};

		$c.win.openMenu(menuNm, menuUrl, menuCode, null, option);

		if ($p.main().pfm_main.scope.main.isMobileSize() == true) {
			$p.main().pfm_main.scope.pfm_header.getWindow().scwin.toggleMenu();
		}

		const deviceWidth = $c.num.parseFloat($("body").css("width"));
		if (deviceWidth < 1280) {
			$p.main().pfm_main.scope.grp_wrap.removeClass("show_menu");
			$p.main().pfm_main.scope.pfm_header.getWindow().btn_toggle_menu.removeClass('on');
		}
	}
};

/**
 * @method
 * @name getMenuNavigation
 * @description 메뉴 Navigation 정보를 가져온다. 상위 메뉴 체인을 재귀로 따라가며 "메뉴명%|%메뉴코드%|%" 를 이어 붙인다.
 * @param {string} menuCode 메뉴 코드
 * @param {string} rsStr 누적 중인 Navigation 문자열 (재귀 호출용, 최초 호출 시 생략)
 * @returns {string} Navigation 문자열
 * @hidden N
 * @example
 * const navi = scwin.getMenuNavigation("100111");
 */
scwin.getMenuNavigation = function (menuCode, rsStr) {
	if (menuCode === "") return rsStr;

	let naviStr = rsStr ? rsStr : "";
	const menuJSON = dlt_menu.getMatchedJSON("MENU_CD", menuCode, true)[0];
	if (!menuJSON) return naviStr;

	naviStr += menuJSON.MENU_NM + "%|%" + menuCode + "%|%";

	if (!$c.util.isEmpty(menuJSON.PARENT_MENU_CD) && menuJSON.PARENT_MENU_CD != "000000000") {
		return scwin.getMenuNavigation(menuJSON.PARENT_MENU_CD, naviStr);
	}
	return naviStr;
};

/**
 * @event
 * @name btn_sample_onclick
 * @description sample 메뉴 클릭 시 발생하는 이벤트 정의
 */
scwin.btn_sample_onclick = function () {
	const menuObj = dlt_menu.getMatchedJSON("MENU_LEVEL", 1);
	scwin.setMenuRelation(menuObj[1].MENU_NM, menuObj[1].SRC_PATH, menuObj[1].MENU_CD);
};

/* ==========================================================================
 * 5. 메뉴 검색
 * ========================================================================== */

/**
 * @event
 * @name dlt_menu_ondataload
 * @description 메뉴 데이터가 load된 후 발생하는 이벤트 정의
 */
scwin.dlt_menu_ondataload = function () {
	$p.main().pfm_main.scope.main.setHeaderMenu();

	scwin.buildMenuSearchList();
};

/**
 * @method
 * @name buildMenuSearchList
 * @description 메뉴 검색창에 띄울 목록을 만든다. 뎁스와 무관하게 화면이 있는 메뉴를 전부 담는다.
 *
 * 뎁스로 거르지 않는다. MENU_LEVEL 은 애초에 믿을 수 없고(sideMenu.json 에 값이 빈
 * 항목이 2026-08-21 기준 34건 있다) 1뎁스에도 화면을 가진 메뉴가 있다.
 *
 * 대신 SRC_PATH 로 거른다. setMenuRelation 은 URL 이 비어도 $c.win.openMenu 를
 * 그대로 부르므로, 화면 없는 대·중분류를 넣으면 골랐을 때 빈 창이 열린다.
 *
 * 표시 문구에 화면명·파일명·메뉴코드를 모두 넣는다. autoComplete 의 search 옵션은
 * 'start' 와 'contain' 뿐이라 컴포넌트가 라벨을 기준으로 걸러낸다. 셋 중 하나로
 * 찾게 하려면 셋 다 라벨에 들어 있어야 한다.
 * @hidden N
 * @example
 * scwin.buildMenuSearchList();
 */
scwin.buildMenuSearchList = function () {
	const rows = [];

	for (let i = 0; i < dlt_menu.getTotalRow(); i++) {
		const menuCd = dlt_menu.getCellData(i, "MENU_CD");
		const srcPath = dlt_menu.getCellData(i, "SRC_PATH");

		// 열 화면이 없는 항목은 검색해도 갈 곳이 없다.
		if ($c.util.isEmpty(srcPath)) continue;

		// /ui/dis/issueinfo/ULDSTF30700.xml -> ULDSTF30700
		const fileNm = srcPath.substring(srcPath.lastIndexOf("/") + 1).replace(".xml", "");

		// 화면명·파일명·메뉴코드를 모두 라벨에 넣어야 셋 중 무엇으로도 검색이 된다. (상단 주석 참고)
		rows.push({
			label: dlt_menu.getCellData(i, "MENU_NM") + " (" + fileNm + " · " + menuCd + ")",
			value: menuCd
		});
	}

	dlt_menuSearch.setJSON(rows);
};

/**
 * @event
 * @name acb_search_onviewchange
 * @description 메뉴 검색창의 보여지는 데이터가 변경 시 발생되는 이벤트 정의
 */
scwin.acb_search_onviewchange = function (info) {
	// 고른 값은 컴포넌트에서 직접 읽는다. 이벤트 payload 의 필드명은 컴포넌트마다 달라
	// info 에 기대면 값이 비어 오는 경우가 있다.
	const menuCd = acb_search.getValue();

	// 안내문구(chooseOption)를 고르거나 입력만 하고 지운 경우에는 아무것도 하지 않는다.
	if ($c.util.isEmpty(menuCd) || menuCd === "none") return;

	const menuObj = dlt_menu.getMatchedJSON("MENU_CD", menuCd);

	if ($c.util.isEmpty(menuObj) || menuObj.length === 0) return;

	// 해당 메뉴의 부모영역을 펼친다.
	scwin.menuExpand(menuObj);

	// menuObj로 onclick 함수를 호출한다.
	scwin.menubtn_onclick(menuObj);
};

/**
 * @method
 * @name menuExpand
 * @description 선택한 메뉴의 상위 메뉴 체인을 따라 트리를 펼친다.
 * 뎁스를 가정하지 않고 PARENT_MENU_CD 를 따라 올라가므로 1~3뎁스 어느 메뉴를
 * 골라도 동작한다. (MENU_LEVEL 은 빈 값이 있어 판단 기준으로 쓰지 않는다)
 * 이미 펼쳐진 메뉴는 다시 클릭하지 않아 접힘 토글이 일어나지 않는다.
 * @param {Array} menuJson 선택한 메뉴의 getMatchedJSON 결과
 * @hidden N
 * @example
 * scwin.menuExpand(dlt_menu.getMatchedJSON("MENU_CD", "100111"));
 */
scwin.menuExpand = function (menuJson) {
	if ($c.util.isEmpty(menuJson) || menuJson.length === 0) return;

	// 최상위부터 순서대로 상위 메뉴 체인을 만든다.
	// (최상위 메뉴의 부모 코드는 빈 값 또는 "000000000" 두 형태가 있다)
	const ancestors = [];
	let parentCd = menuJson[0].PARENT_MENU_CD;
	while (!$c.util.isEmpty(parentCd) && parentCd != "000000000") {
		const parent = dlt_menu.getMatchedJSON("MENU_CD", parentCd);
		if ($c.util.isEmpty(parent) || parent.length === 0) break;
		ancestors.unshift(parent[0]);
		parentCd = parent[0].PARENT_MENU_CD;
	}

	// 1뎁스 메뉴를 고른 경우 펼칠 상위가 없다.
	if (ancestors.length === 0) return;

	// 1depth: 위치를 찾아 아직 접혀 있는 경우에만 클릭해 펼친다.
	let idx1 = -1;
	for (let i = 0; i < gen_depth1.getLength(); i++) {
		if (gen_depth1.getChild(i, 'btn_depth1').getUserData('menuCode') == ancestors[0].MENU_CD) {
			idx1 = i;
			break;
		}
	}
	if (idx1 < 0) return;

	if (!gen_depth1.getChild(idx1, 'grp_1depth').hasClass('on')) {
		gen_depth1.getChild(idx1, 'btn_depth1').click();
	}

	if (ancestors.length < 2) return;

	// 2depth: 동일하게 접혀 있는 경우에만 클릭한다.
	const gen2 = gen_depth1.getChild(idx1, 'gen_depth2');
	let idx2 = -1;
	for (let i = 0; i < gen2.getLength(); i++) {
		if (gen2.getChild(i, 'btn_depth2').getUserData('menuCode') == ancestors[1].MENU_CD) {
			idx2 = i;
			break;
		}
	}
	if (idx2 < 0) return;

	if (!gen2.getChild(idx2, 'grp_2depth').hasClass('on')) {
		gen2.getChild(idx2, 'btn_depth2').click();
	}
};

/**
 * @event
 * @name btn_allSearch_onclick
 * @description 메뉴 검색 버튼을 클릭 시 발생하는 이벤트
 */
scwin.btn_allSearch_onclick = function () {
	gr_search_field.toggleClass("active");
};

/* ==========================================================================
 * 6. 즐겨찾기
 * ========================================================================== */

/**
 * @method
 * @name updateFav
 * @description 즐겨찾기 등록 업데이트 (추가/삭제), $c.updateFav 함수는 Scope=true가 적용된 WFrame에서는 사용해서는 안됨
 * @param {string} menuCode 메뉴코드
 * @param {string} favStatus 즐겨찾기 업데이트를 위한 상태 값 (F: 추가, T: 삭제)
 * @hidden N
 * @example
 * scwin.updateFav("100111", "F");
 */
scwin.updateFav = function (menuCode, favStatus) {
	if (favStatus == "F") {
		favStatus = "I";
	} else if (favStatus == "T") {
		favStatus = "D";
	}

	dma_fav.set("MENU_CD", menuCode);
	dma_fav.set("STATUS", favStatus);
	$c.sbm.execute(sbm_updateFav);

	if (favStatus == "D") {
		// 즐겨찾기 삭제인 경우 - removeChild 시 인덱스가 당겨지므로 역순으로 순회한다.
		for (let i = gen_fav.getLength() - 1; i >= 0; i--) {
			const menuCd = gen_fav.getChild(i, 'btn_fav').getUserData('menuCode');
			if (menuCd == menuCode) {
				gen_fav.removeChild(i);
			}
		}
	} else if (favStatus == "I") {
		// 즐겨찾기 추가인 경우
		const menu = dlt_menu.getMatchedJSON('MENU_CD', menuCode);
		const idx = gen_fav.insertChild();
		const child = gen_fav.getChild(idx, 'btn_fav');
		child.setValue(menu[0].MENU_NM);
		child.setUserData('menuCode', menu[0].MENU_CD);
	}
};

/**
 * @method
 * @name setUpdateFavCallback
 * @description 즐겨찾기 등록 업데이트 후 callback 함수. 업데이트 건수가 있으면 결과 메시지를 띄우고 즐겨찾기 목록을 재조회한다.
 * @param {Object} e submit 완료 이벤트 (responseJSON.updateResult: "상태:건수", responseJSON.rsMsg: 결과 메시지)
 * @hidden N
 * @example
 * scwin.setUpdateFavCallback(e);
 */
scwin.setUpdateFavCallback = function (e) {
	const updateResult = e.responseJSON.updateResult || "";
	const updateInfoArr = updateResult.split(":");
	const updateStatus = updateInfoArr[0];
	const updateNum = updateInfoArr[1];

	// 업데이트가 0건 이상일 경우 즐겨찾기 리스트 갱신
	if ($c.num.parseInt(updateNum) > 0) {
		$c.sbm.resultMsg(e.responseJSON.rsMsg);
		$c.sbm.execute(sbm_selectFavList);
	}
};

/**
 * @method
 * @name hasFavCode
 * @description 즐겨찾기 리스트에서 menuCode가 추가되어 있는지 확인 후 개수를 반환한다. 없으면 0, 있으면 1 이상.
 * @param {string} menuCode 메뉴코드
 * @returns {number} 즐겨찾기에 등록된 해당 메뉴코드의 개수
 * @hidden N
 * @example
 * if (scwin.hasFavCode("100111") > 0) { ... }
 */
scwin.hasFavCode = function (menuCode) {
	return (dlt_fav.getMatchedIndex("MENU_CD", menuCode, true)).length;
};

/**
 * @event
 * @name btn_fav_onclick
 * @description 즐겨찾기 메뉴 버튼을 클릭했을 때 해당 화면 호출.
 * @hidden N
 */
scwin.btn_fav_onclick = function () {
	// menuObj에 정보가 없는 경우 직접 찾는다
	const idx = this.getGeneratedIndex();
	const menu = this.getGenerator().getChildren()[idx];
	const menuNm = menu.getChildren()[0].getValue();
	const menuObj = dlt_menu.getMatchedJSON("MENU_NM", menuNm);

	// 바인딩
	scwin.setMenuRelation(menuObj[0].MENU_NM, menuObj[0].SRC_PATH, menuObj[0].MENU_CD);
};

/**
 * @event
 * @name btn_FavMenuNode_onclick
 * @description 즐겨찾기 메뉴 node 클릭 시 발생하는 이벤트 정의
 */
scwin.btn_FavMenuNode_onclick = function () {
	const tLabel = this.getSelectedLabel(); // 선택된 노드 label값을 가져와서 변수에 담는다.
	const tCode = this.getSelectedValue(); // 선택된 노드 value값을 가져와서 변수에 담는다.
	const menuInfo = dlt_menu.getMatchedJSON("MENU_CD", tCode);
	let tURL = "";

	if (!$c.util.isEmpty(menuInfo) && menuInfo.length > 0) {
		tURL = menuInfo[0].SRC_PATH;
	}

	scwin.setMenuRelation(tLabel, tURL, tCode, "Tree");
};

/* ==========================================================================
 * 7. 표시 형식
 * ========================================================================== */

/**
 * @method
 * @name dispFmUserName
 * @description 사용자 이름 뒤에 '님'을 붙인다
 * @param {string} val 사용자명이 담긴 데이터
 * @returns {string} '님'이 붙은 사용자명 (빈 값이면 그대로 반환)
 * @hidden N
 * @example
 * scwin.dispFmUserName("홍길동"); // "홍길동님"
 */
scwin.dispFmUserName = function (val) {
	if (val) {
		val += "님";
	}
	return val;
};
